"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["48939"],{92274(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.formulario_portavel.operacao_de_agregado_invalida","status":422,"titulo":"A opera\xe7\xe3o do agregado \xe9 EXISTE ou VALORES_PRESENTES"},"descricao":{"codigo":"uniplus.formulario_portavel.operacao_de_agregado_invalida","requisitos":[],"oQueAconteceu":["A avalia\xe7\xe3o de um formul\xe1rio sem cadastro confere as regras de um formul\xe1rio apresentado contra respostas simuladas, sem gravar nada nem registrar o conte\xfado enviado. Um resumo sobre um grupo repet\xedvel, como \\"existe membro que...\\" ou \\"categorias presentes na lista\\", traz uma `operacao` que n\xe3o \xe9 `EXISTE` nem `VALORES_PRESENTES`, inclusive o texto vazio. A mensagem identifica o c\xf3digo `{c\xf3digo\\\\}` e informa as opera\xe7\xf5es aceitas.","A recusa vem no corpo da resposta, com o c\xf3digo e o `detail` que traz a mensagem, sem lista `errors`. As regras recebidas s\xe3o lidas por inteiro antes da avalia\xe7\xe3o, e a leitura para na primeira recusa, nesta ordem: o elemento nulo, as p\xe1ginas (com os itens e os grupos de cada uma), os termos, as deriva\xe7\xf5es, os resumos de grupo e, por fim, o conjunto.","As propriedades de texto que o corpo n\xe3o pode omitir, como o c\xf3digo, a obrigatoriedade e a opera\xe7\xe3o, ausentes ou nulas, s\xe3o recusadas antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo."],"comoResolver":["Informe `EXISTE` ou `VALORES_PRESENTES` na `operacao` do resumo de grupo e repita a avalia\xe7\xe3o."],"ondeAparece":["Avalia\xe7\xe3o de formul\xe1rio sem cadastro"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Formulario portavel"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);